		return ! empty( $parts['scheme'] ) && ! empty( $parts['host'] ) && empty( $parts['user'] ) && empty( $parts['pass'] ) && isset( $home['host'] ) && strtolower( $parts['host'] ) === strtolower( $home['host'] ) && in_array( strtolower( $parts['scheme'] ), array( 'http', 'https' ), true );
