on.addEventListener("click",function(){var out=button.closest(".digitalisimo-front-ai-card").querySelector(".digitalisimo-front-ai-result");button.disabled=true;out.textContent="Analizando la landing…";fetch("' . esc_js( rest_url( 'digitalisimo-ai/v1/complete' ) ) . '",{method:"POST",headers:{"Content-Type":"application/json","X-WP-Nonce":"' . esc_js( wp_create_nonce( 'wp_rest' ) ) . '"},body:JSON.stringify({profile:"seo",prompt:button.dataset.prompt})}).then(function(response){return response.json()}).then(function(data){if(data.answer)plan(out,data.answer);else out.textContent=data.message||"No fue posible generar recomendaciones."}).catch(function(){out.textContent="Error de conexión."}).finally(function(){button.disabled=false})})})})();</script></section>
